int liczba = 0;
int minimum, maksimum, jasnosc;

unsigned long czasOdczytu = 0;

const byte cyfry[10] = {
  0b0000001, // 0
  0b1001111, // 1
  0b0010010, // 2
  0b0000110, // 3
  0b1001100, // 4
  0b0100100, // 5
  0b0100000, // 6
  0b0001111, // 7
  0b0000000, // 8
  0b0000100  // 9
};

void Znak(int numer) {
  byte wzor = cyfry[numer];

  // Segmenty A-F na D2-D7
  byte portD = ((wzor >> 1) & 0b00111111) << 2;

  // Segment G na D8
  byte portB = wzor & 1;

  PORTD = (PORTD & 0b00000011) | portD;

  if (portB) {
    PORTB |= 0b00000001;
  } else {
    PORTB &= 0b11111110;
  }
}

void Wyswietl() {

  // Wyłącz obie cyfry
  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  // Dziesiątki
  Znak(liczba / 10);
  digitalWrite(10, HIGH);
  delay(3);
  digitalWrite(10, LOW);

  // Jedności
  Znak(liczba % 10);
  digitalWrite(11, HIGH);
  delay(3);
  digitalWrite(11, LOW);
}

void setup() {

  DDRD |= 0b11111100;
  DDRB |= 0b00001101;

  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  minimum = analogRead(A0);
  maksimum = minimum;
}

void loop() {

  Wyswietl();

  if (millis() - czasOdczytu >= 100) {

    czasOdczytu = millis();

    jasnosc = analogRead(A0);

    if (jasnosc < minimum)
      minimum = jasnosc;

    if (jasnosc > maksimum)
      maksimum = jasnosc;

    if (maksimum > minimum) {
      liczba = map(jasnosc, minimum, maksimum, 0, 99);
    } else {
      liczba = 0;
    }

    liczba = constrain(liczba, 0, 99);
  }
}
